import { JSONSchemaCustom } from '@/components/schema';
import file from '@/store/file';
import app from '@/store/app';
import { Pattern } from '@/types/pattern';
import { getUuid } from '@/utils';
import ajax from '@/utils/ajax';
import { createZip, createZipFile, parseZipFile } from '@/utils/zip';
import { Message, Modal } from '@arco-design/web-react';
import config from 'mainConfig';
import dayjs from 'dayjs';
import { observable, action, makeObservable } from 'mobx';
import dev from '@/store/dev';
import { AppVersion } from './interface';
import ProdStore from './prod';
import dir from '@/store/dir';


class Store {

    @observable loading = false;
    @action setLoading = (bool: boolean) => {
        this.loading = bool;
    }
    
    @observable activeTab = "prod";
    @action setActiveTab = (tabKey: string) => {
        this.activeTab = tabKey;
        this.getList();
    }


    @observable visible = false;
    @action setVisible = (bool) => {
        this.visible = bool;
    }

    downItem: AppVersion = {
        id: '',
        description: '',
        versionNumber: 0,
        releaseNotes: {
            webZip: ''
        }
    };
    @observable downloadVisible = false;
    @action setDownloadVisible = (bool) => {
        this.downloadVisible = bool;
    }

    initValues = {};

    schema: JSONSchemaCustom = {
        type: "object",
        properties: {
            versionNumber: {
                "title": "应用版本号",
                description: "应用版本格式要符合 xx.xx.xx",
                formItemProps: {
                    rules: [
                        { required: true },
                        { match: new RegExp(Pattern.version), message: "请检查版本号格式是否正确" },
                        { 
                            validator: (value, callback) => {
                                const list = this.activeTab == 'test'? this.list : this.prodList;
                                const versions = list.map((item) => item.versionNumber);
                                if(versions.length){
                                    if(versions.includes(value)){
                                        return callback("当前版本号已经存在")
                                    }
                                    if(value < versions[0]) return callback(`当前版本号需要大于${versions[0]}`);
                                }
                            },
                        }
                    ]
                }
            },
            description: {
                title: "版本描述",
                format: "text"
            }
        },
        required: ['versionNumber']
    }

    constructor(){
        makeObservable(this);
        this.init();
    }

    // 测试版本
    @observable list = [];
    @action setList = (data) => {
        this.list = data;
    }

    // 生产版本（列表）
    @observable prodList = [];
    @action setProdList = (data) => {
        this.prodList = data;
    }
    

    init = () => {
        this.getList();
    }

    getList(){
        if(this.activeTab == 'test'){
            this.getTestList();
        }else {
            this.getProdList();
        }
    }

    getTestList(){
        this.setLoading(true);
        ajax.post('/apijson/get', {
            "AppVersion[]": {
                "count": 20,
                "AppVersion": {
                    "env": "test",
                    "@order": "versionNumber-"
                }
            }
        }).then((res) => {
            this.setList(res.AppVersion)
        }).finally(() => {
            this.setLoading(false);
        })
    }


    getProdList(){
        this.setLoading(true);
        ajax.post('/apijson/get', {
            "AppVersion[]": {
                "count": 20,
                "AppVersion": {
                    "env": "prod",
                    "@order": "versionNumber-"
                }
            }
        }).then((res) => {
            this.setProdList(res.AppVersion)
        }).finally(() => {
            this.setLoading(false);
        })
    }


    deleteVersion = (item: any) => {
        Modal.confirm({
            title: "删除确认",
            content: `请确认是否删除${item.versionNumber}版本`,
            onOk: () => {
                return ajax.post('/apijson/delete', {
                    "AppVersion": {
                        "id": item.id
                    }
                }).then((res) => {
                    Message.success("删除成功")
                    this.init();
                })
            }
        })
    }


    incrementVersion = () => {
        const list = this.activeTab == 'test'? this.list : this.prodList;
        if(!list[0]) return "1.0.0";
        const { versionNumber: version } = list[0]
        // 将版本号拆分成主版本号、次版本号和修订版本号
        var parts = version.split('.');
        var major = parseInt(parts[0], 10);
        var minor = parseInt(parts[1], 10);
        var patch = parseInt(parts[2], 10);
    
        // 将修订版本号加一
        patch++;
    
        // 如果修订版本号达到10，增加次版本号，修订版本号重置为0
        if (patch === 10) {
            minor++;
            patch = 0;
        }
    
        // 如果次版本号达到10，增加主版本号，次版本号和修订版本号都重置为0
        if (minor === 10) {
            major++;
            minor = 0;
            patch = 0;
        }
    
        // 返回新的版本号
        return major + '.' + minor + '.' + patch;
    }

    /**
     * 创建页面全局文件
     */
    createPageFileStr = (page: any) => {

        if(!page.jsxRender) return "";
        return `
            export function createPage_${page.id.replace(/\-/g, '')}(global){
                ${page.jsxRender}
            };
        `;
    }



    /**
     * 创建全局配置文件
     */
    createCssFileStr = (pages: any[], modules: any[]) => {
        let cssStr = '';
        for (const page of pages) {
            const { id, title, extraInfo } = page;
            if(extraInfo && extraInfo.cssStr){
                cssStr += `/** pageId: ${id}【${title}】 */\n${extraInfo.cssStr}`
            }
        }
        for (const module of modules) {
            const { id, name, nickname, extraInfo } = module;
            if(extraInfo && extraInfo.cssStr){
                cssStr += `/** moduleId: ${id}【${nickname || name}】 */\n ${extraInfo.cssStr}`
            }
        }
        return cssStr;
    }


    ids = {};
    getFileUuid(){
        let hash = getUuid("hash");
        while(this.ids[hash]){
            hash = getUuid("hash");
        }
        return `${getUuid('hash').slice(0,1)}${hash}`;
    }
    

    // 获取app对应的文件包
    getAppFileInfo = async (version: number) => {
        const data = await import(`${config.CDNURL}/version/app/${app.info.mark}/${version}.js`).then((res) => {
            return res.default;
        })
        console.log('getAppFileInfo', data)
        const { routes, pages, adminRoutes, modules = [] } = data;
        let files = [];
        let pageMap: any = {};
        let pageObj = { content: "", fileId: getUuid() };
        for (const page of pages) {
            const pageStr = this.createPageFileStr(page);
            if(pageStr){
                pageObj.content += this.createPageFileStr(page);
                pageMap[page.id] = pageObj.fileId;
            }
            if(pageObj.content.length > 65536){
                // 大致判断当前页面内容是否超过了 64kb，没超过多个页面合并加载
                files.push(pageObj);
                pageObj = { content: "", fileId: getUuid() };
            }
        }
        if(pageObj.content.length){
            files.push(pageObj);
        }
        const date = dayjs().format("YYYY-MM-DD HH:mm:ss");
        const fileMap = {};
        // 创建全局js 文件
        let moduleStr = '';
        for (const item of modules) {
            if(item.jsxRender){
                moduleStr += `"${item.moduleId}": () => { //${item.nickname || item.name}\n ${item.jsxRender} },\n`;   
            }else {
                moduleStr += `"${item.moduleId}": () => { return null },\n`;
            }
        }
        let fileStr = '';
        for (const file of files) {
            const uuid = this.getFileUuid();
            fileMap[file.fileId] = uuid
            fileStr += `"${file.fileId}": () => import("./index.${uuid}.js"),\n`;
        }
        const cssStr = this.createCssFileStr(pages, modules);
        const appStr = `
            export function createApp(global){

                return {
                    date: "${date}",
                    routes: ${JSON.stringify(routes)},
                    adminRoutes: ${JSON.stringify(adminRoutes)},
                    pageMap: ${JSON.stringify(pageMap)},
                    fileMap: { ${fileStr} },
                    moduleNode: { ${moduleStr} }
                }
            }
        `

        return { cssStr, appStr, files, fileMap }
    }



    // 创建应用压缩包
    createAppZip = async () => {
        const list = await parseZipFile(dir.getWeb());
        await dev.init();
        const { cssStr, appStr, files, fileMap } = await dev.getAppFileInfo();
        // return;
        for (const file of files) {
            list.push({
                url: `dist/assets/index.${fileMap[file.fileId]}.js`,
                text: file.content,
            })
        }
        const appFile = `index.${this.getFileUuid()}.js`;
        const cssFile = `index.${this.getFileUuid()}.css`;
        list.push({
            url: `dist/assets/${appFile}`,
            text: appStr
        })
        list.push({
            url: `dist/assets/${cssFile}`,
            text: cssStr,
        })

        // tailwindcss
        const tailwindcss = await dev.getTailwindcss();
        list.push({
            url: `dist/assets/tailwindcss.css`,
            text: tailwindcss,
        })

        let status = 0;
        for (const item of list) {
            // 更新文件
            // console.log('item', item, item.url.indexOf("build."))
            if(item.url == "dist/build.html"){
                item.url = "dist/index.html"
                const index = item.text.indexOf('</head>');
                let linkStr = `\t<link rel="stylesheet" href="./assets/${cssFile}">\n\t`;
                // 加载css 文件
                item.text = `${item.text.slice(0,index)}${linkStr}${item.text.slice(index)}`
                status += 1;
            }else if(item.url.indexOf("build.") !== -1 && item.text.indexOf("fjZF1r0lBovWyUTSNXuzayPr5qoXGl2s1vBgI8h") !== -1){
                // 加载js 文本
                item.text = item.text.replace(`"fjZF1r0lBovWyUTSNXuzayPr5qoXGl2s1vBgI8h"`, `import('./${appFile}')`)
                status += 3;
            }
        }

        const fileList = await file.updateFileList();
        // 合并到压缩包
        for (const item of fileList) {
            list.push({
                url: `dist${item.url}`,
                text: item.text,
            })
        }

        if(status == 4){
            // 创建压缩包
            return createZipFile(list)
        }else {
            Message.error(`创建版本识别，压缩包识别失败，请联系管理员。 错误码：${status}`)
            return Promise.reject(`创建版本识别，压缩包识别失败，请联系管理员。 错误码：${status}`);
        }
    }


    // 下载web 应用版本包（功能暂时弃用）
    downWebVersion = async (version: number) => {
        const list = await parseZipFile(dir.getWeb());
        console.log('parseZipFile', list)
        const { cssStr, appStr, files, fileMap } = await this.getAppFileInfo(version);
        // return;
        for (const file of files) {
            list.push({
                url: `dist/assets/index.${fileMap[file.fileId]}.js`,
                text: file.content,
            })
        }
        const appFile = `index.${this.getFileUuid()}.js`;
        const cssFile = `index.${this.getFileUuid()}.css`;
        list.push({
            url: `dist/assets/${appFile}`,
            text: appStr
        })
        list.push({
            url: `dist/assets/${cssFile}`,
            text: cssStr,
        })

        let status = 0;
        for (const item of list) {
            // 更新文件
            // console.log('item', item, item.url.indexOf("build."))
            if(item.url == "dist/build.html"){
                item.url = "dist/index.html"
                const index = item.text.indexOf('</head>');
                let linkStr = `\t<link rel="stylesheet" href="./assets/${cssFile}">\n\t`;
                // 加载css 文件
                item.text = `${item.text.slice(0,index)}${linkStr}${item.text.slice(index)}`
                status += 1;
            }else if(item.url.indexOf("build.") !== -1 && item.text.indexOf("fjZF1r0lBovWyUTSNXuzayPr5qoXGl2s1vBgI8h") !== -1){
                // 加载js 文本
                item.text = item.text.replace(`"fjZF1r0lBovWyUTSNXuzayPr5qoXGl2s1vBgI8h"`, `import('./${appFile}')`)
                status += 3;
            }
        }

        const fileList = await file.updateFileList();
        // 合并到压缩包
        for (const item of fileList) {
            list.push({
                url: `dist${item.url}`,
                text: item.text,
            })
        }


        if(status == 4){
            Message.success("版本创建成功");
            return createZip(list, `${app.info.mark}.web.zip`)
        }else {
            Message.error(`创建版本识别，压缩包识别失败，请联系管理员～ ${status}`);
        }
    }




    
    // 创建生产版本
    createProdZip = async () => {
        const prod = new ProdStore();
        const zip = await prod.init();
        return zip;
    }
}


export default Store;
