import React, { useEffect, useState } from "react";
import { Alert, Avatar, Button, Card, Dropdown, Form, Grid, Menu, Message, Modal, Space, Tabs, Tooltip, Typography } from "@arco-design/web-react";
import DevCard from "./components/DevCard";
import { IconExclamationCircle, IconMore, IconSync } from "@arco-design/web-react/icon";
import app from "@/store/app";
import _ from 'lodash';
import { SchemaForm } from "@/components/schema";
import { useObserver } from "mobx-react-lite";
import Store from './store';
import ajax, { uploadVersion } from "@/utils/ajax";
import DownCard from './components/DownCard';
import { AsyncButton } from "@/components/custom";
import dir from "@/store/dir";
const { Meta } = Card;


const AppVersion = () => {
    const [store] = useState(() => new Store());

    return useObserver(() => {
        const { visible, setVisible, downloadVisible, setDownloadVisible } = store;
        const [form] = Form.useForm();

        return (
            <div style={{ height: '100%' }}>
                <Alert
                    type='warning'
                    content='当前应用还未激活，暂时无法修改'
                    action={
                        <Button size='mini' type="text">
                          去激活
                        </Button>
                    }
                />
                <Card title="应用概况"
                    style={{ marginBottom: 20 }}
                    extra={(
                        <React.Fragment>
                            <Button type="text"
                                onClick={() => {
                                    window.open(`#/preview/${app.info.mark}/`)
                                }}
                            >
                                立即预览
                            </Button>
                        </React.Fragment>
                    )}
                >
                    <Grid.Row gutter={[20, 20]}>
                        <Grid.Col span={6}>
                            <DevCard type="manage" />
                        </Grid.Col>
                        <Grid.Col span={6}>
                            <DevCard type="pc" />
                        </Grid.Col>
                    </Grid.Row>
                </Card>
                <Card loading={store.loading}>
                    <Tabs
                        activeTab={store.activeTab}
                        extra={(
                            <AsyncButton type="primary"
                                onClick={() => {
                                    setVisible(true);
                                    store.initValues = {
                                        versionNumber: store.incrementVersion()
                                    }
                                }}
                            >
                                创建应用版本
                            </AsyncButton>
                        )}
                        onChange={store.setActiveTab}
                    >
                        <Tabs.TabPane key="test" title="测试版本">
                            {store.list.map((item) => {
                                return (
                                    <Card
                                        bordered
                                        key={item.id}
                                        style={{ marginBottom: 20 }}
                                        title={item.versionNumber}
                                        extra={(
                                            <Space>
                                                <Button type="text"
                                                    onClick={() => {
                                                        store.downItem = item;
                                                        setDownloadVisible(true)
                                                    }}
                                                >下载</Button>
                                                <Dropdown
                                                    droplist={(
                                                        <Menu>
                                                            {/* <Menu.Item key='1'
                                                                onClick={() => {
                                                                    store.deleteVersion(item)
                                                                }}
                                                            >
                                                                删除
                                                            </Menu.Item> */}
                                                            <Menu.Item key="2"
                                                                onClick={() => {
                                                                    window.open(`#/v/${app.info.mark}/${item.versionNumber}/`)
                                                                }}
                                                            >
                                                                预览
                                                            </Menu.Item>
                                                        </Menu>
                                                    )}
                                                    position='bl'
                                                >
                                                    <Button type="text" icon={<IconMore />} />
                                                </Dropdown>
                                            </Space>
                                        )}
                                        actions={[
                                            <Typography.Text>
                                                发布时间：{item.createdAt}
                                            </Typography.Text>
                                        ]}
                                    >
                                        <Meta
                                            avatar={
                                            <Space>
                                                <Avatar size={24}>A</Avatar>
                                                <Typography.Text>{item.userId}</Typography.Text>
                                            </Space>
                                            }
                                            // title='Card Title'
                                            description={item.description}
                                        />
                                    </Card>
                                )
                            })}
                        </Tabs.TabPane>
                        <Tabs.TabPane 
                            key="prod"
                            title={(
                                <div className="flex items-center">
                                    <span>生产版本</span>
                                    <Tooltip content="生产版本可构建源码用于二次开发">
                                        <IconExclamationCircle />
                                    </Tooltip>
                                </div>
                            )}
                        >
                           {store.prodList.map((item) => {
                                return (
                                    <Card
                                        bordered
                                        key={item.id}
                                        style={{ marginBottom: 20 }}
                                        title={item.versionNumber}
                                        extra={(
                                            <Space>
                                                <Button type="text"
                                                    onClick={() => {
                                                        store.downItem = item;
                                                        setDownloadVisible(true)
                                                    }}
                                                >下载</Button>
                                                <Dropdown
                                                    droplist={(
                                                        <Menu>
                                                            {/* <Menu.Item key='1'
                                                                onClick={() => {
                                                                    store.deleteVersion(item)
                                                                }}
                                                            >
                                                                删除
                                                            </Menu.Item> */}
                                                            <Menu.Item key="2"
                                                                onClick={() => {
                                                                    window.open(`#/v/${app.info.mark}/${item.versionNumber}/`)
                                                                }}
                                                            >
                                                                预览
                                                            </Menu.Item>
                                                        </Menu>
                                                    )}
                                                    position='bl'
                                                >
                                                    <Button type="text" icon={<IconMore />} />
                                                </Dropdown>
                                            </Space>
                                        )}
                                        actions={[
                                            <Typography.Text>
                                                发布时间：{item.createdAt}
                                            </Typography.Text>
                                        ]}
                                    >
                                        <Meta
                                            avatar={
                                            <Space>
                                                <Avatar size={24}>A</Avatar>
                                                <Typography.Text>{item.userId}</Typography.Text>
                                            </Space>
                                            }
                                            // title='Card Title'
                                            description={item.description}
                                        />
                                    </Card>
                                )
                            })}
                        </Tabs.TabPane>
                    </Tabs>
                </Card>
                {store.activeTab == 'test'? (
                    <Modal
                        title="创建应用测试版本"
                        visible={visible}
                        onCancel={() => {
                            setVisible(false)
                        }}
                        onOk={() => {
                            return form.validate().then(async (res) => {
                                const { versionNumber } = res;
                                const zipFile = await store.createAppZip();
                                const { mark } = app.info;
                                const resData = await uploadVersion(
                                    zipFile,
                                    dir.app.getTestZipPath(mark, versionNumber)
                                );
                                // console.log('resData', resData)
                                // 创建版本
                                return ajax.post('/app/versionCreate', {
                                    releaseNotes: {
                                        webZip: resData.url,
                                    },
                                    ...res
                                }).then((res) => {
                                    Message.success("版本创建成功")
                                    setVisible(false);
                                    store.init();
                                })
                            })
                        }}
                        style={{ width: 800 }}
                        unmountOnExit
                    >
                        <SchemaForm
                            form={form}
                            initialValues={store.initValues}
                            layout="vertical"
                            labelWidth={200}
                            generagteProps={{
                                cols: 24
                            }}
                            schema={store.schema}
                        />
                    </Modal>
                ): (
                    <Modal
                        title="创建应用生产版本"
                        visible={visible}
                        onCancel={() => {
                            setVisible(false)
                        }}
                        onOk={() => {
                            return form.validate().then(async (res) => {
                                const { versionNumber } = res;
                                const zipFile = await store.createProdZip();
                                const { mark } = app.info;

                                // 上传文件
                                const resData = await uploadVersion(
                                    zipFile,
                                    dir.app.getProdZipPath(mark, versionNumber)
                                );

                                // 创建版本
                                return ajax.post('/app/versionCreate-prod', {
                                    releaseNotes: {
                                        webZip: resData.url,
                                    },
                                    ...res
                                }).then((res) => {
                                    Message.success("版本创建成功")
                                    setVisible(false);
                                    store.init();
                                })
                            })
                        }}
                        style={{ width: 800 }}
                        unmountOnExit
                    >
                        <SchemaForm
                            form={form}
                            initialValues={store.initValues}
                            layout="vertical"
                            labelWidth={200}
                            generagteProps={{
                                cols: 24
                            }}
                            schema={store.schema}
                        />
                    </Modal>
                )}
                <Modal
                    title="版本下载"
                    visible={downloadVisible}
                    onCancel={() => {
                        setDownloadVisible(false)
                    }}
                    style={{ width: 800 }}
                    unmountOnExit
                >
                    <DownCard store={store} {...store.downItem}/>
                </Modal>
            </div>
        )
    })
}


export default AppVersion;