import { ModuleItem } from "@/components/CustomPage/interface";
import app from "@/store/app";
import dir from "@/store/dir";
import { MenuItem } from "@/types/menu";
import { PageItem } from "@/types/page";
import { PluginInfo } from "@/types/plugin";
import { convertToTree, flattenTree, getSpecificValues } from "@/utils";
import ajax from "@/utils/ajax";
import { generateReadableJson } from "@/utils/json";
import { createZip, createZipFile, parseZipFile } from "@/utils/zip";
import { CustomPageStore, moduleStore } from "react-converter-code";
import language from "@/store/language";
import dev from '@/store/dev';
import file from "@/store/file";

class Prod {

    rootPath = "template";
    list: Array<{ url: string, text: any }> = [];

    pages: PageItem[] = [];
    modules: ModuleItem[] = [];
    plugins: PluginInfo[] = [];
    menus: MenuItem[] = [];
    languages: any[] = [];  // 所有多语言Keys

    adminMenus: MenuItem[] = [];
    adminPages: PageItem[] = [];
    adminModules: ModuleItem[] = [];


    getTreeMenus = (list: MenuItem[]) => {
        return getSpecificValues(convertToTree(
            list.map((o) => {
                return { 
                    ...o,
                    // path: o.path.slice(0,1) == '/'? o.path.slice(1) : o.path,
                    requiredPermissions: o.authority? [{ resource: o.authority }] : undefined,
                    path: o.path,
                    key: String(o.id),
                    originPath: o.path,
                }
            })
        ), (item, parentItem) => {
            if(!parentItem) return {
                ...item,
                paths: [item.path],
                path: `/${[item.path].filter((k) => !['/', '*'].includes(k)).join('/')}`
            };
            let paths = [ ...parentItem.paths, item.path ];
            return {
                ...item,
                paths,
                path: `/${paths.filter((k) => !['/', '*'].includes(k)).join('/')}`
            }
        })
    }

    // 获取生产环境数据
    getAppProdInfo = async () => {
        const { plugins = {} } = app.info.extraInfo || {}
        const pluginList = Object.values(plugins).filter((o) => o.isActive);
        const pluginIds = pluginList.filter((o) => !o.version).map((o) => o.id);
        const pluginNode = {};
        // 获取应用版本信息
        const info = await ajax.post('/app/appInformation-code', {
            projectId: app.info.projectId,
            pluginIds
        }).then((data) => {
            const { modules, pages, menus, plugins, project } = data;
            for (const plugin of plugins) {
                pluginNode[plugin.id] = plugin;
            }
            this.plugins = plugins;
            this.menus = menus;
            this.pages = pages.map((o) => ({ ...o, content: JSON.parse(o.content || '{}') }));
            this.modules = modules.map((o) => ({ ...o, content: JSON.parse(o.content || '{}') }));
            return data;
        })

        const { project } = info;

        // console.log('pluginList', pluginList)

        // 加载项目插件信息
        await Promise.all(
            [
                import(dir.project.get(project.id, project.releaseVersion)).then((res) => res.default),
                ...pluginList.map((o) => { 
                    return { ...o, version: o.version || pluginNode[o.id]?.releaseVersion }
                }).filter((o) => Boolean(o.version)).map((o) => {
                    return import(dir.plugin.get(o.id, o.version)).then((res) => {
                        return res.default;
                    })
                })
            ]
        ).then((list) => {
            // console.log('admin-list', list)
            for (const item of list) {
                const { modules, pages, menus, languages } = item;
                // 加载所有页面信息
                this.adminPages = this.adminPages.concat(pages);
                this.adminModules = this.adminModules.concat(modules);
                this.adminMenus = this.adminMenus.concat(menus);
                this.languages = this.languages.concat(languages);
            }
        })
    }

    
    /**
     * 写入app 模块信息
     */
    createAppModules = async () => {
        for (const element of this.modules) {
            element.key = element.moduleId;
            element.source = 'custom';
            moduleStore.addElement(element as any);   
        }
        // console.log('createAppModules', this.modules)
        await Promise.all(this.modules.map((o) => {
            return (async () => {
                const { content, ...item } = o;
                const customStore = new CustomPageStore({ isComponent: true, isBuild: true, uid: item.key })
                await customStore.setData(content)
                const { indexText, storeText } = await customStore.getTextFiles()
                this.list = this.list.concat([
                    {
                        url: `${this.rootPath}/src/components/${item.name}/index.tsx`,
                        text: indexText,
                    },
                    {
                        url: `${this.rootPath}/src/components/${item.name}/store.ts`,
                        text: storeText
                    }
                ])
                if(content.lessStr){
                    this.list.push({
                        url: `${this.rootPath}/src/components/${item.name}/style.less`,
                        text: content.lessStr,
                    })
                }
            })()
        }))
    }

    /**
     * 写入app 页面信息
     */
    createAppPages = async () => {
        const list = await Promise.all(this.pages.map((o) => {
            return (async () => {
                const { content, ...item } = o;
                const customStore = new CustomPageStore({ isBuild: true })
                await customStore.setData(content)
                const { indexText, storeText } = await customStore.getTextFiles()
                return {
                    ...item,
                    indexText,
                    storeText,
                    lessText: content.lessStr,
                }
            })()
        }))

        const map = new Map(list.map((o: any) => [o.id, o]));

        // console.log('item', this.menus, map)
        for (const menu of this.menus) {
            const item = map.get(menu.pageId);
            if(item){
                // 判断当前页面是否已经使用到
                this.list = this.list.concat([
                    {
                        url: `${this.rootPath}/src/pages/${item.title}/index.tsx`,
                        text: item.indexText,
                    },
                    {
                        url: `${this.rootPath}/src/pages/${item.title}/store.ts`,
                        text: item.storeText
                    }
                ])
                if(item.lessText){
                    this.list.push({
                        url: `${this.rootPath}/src/pages/${item.title}/style.less`,
                        text: item.lessText,
                    })
                }
            }
        }
    }



    /**
     * 写入管理端 模块信息
     */
    createAdminModules = async () => {
        for (const element of this.adminModules) {
            element.key = element.moduleId;
            moduleStore.addElement(element as any);   
        }
        await Promise.all(this.adminModules.map((o) => {
            return (async () => {
                const { content, ...item } = o;
                const customStore = new CustomPageStore({ isComponent: true, isBuild: true, uid: item.key })
                await customStore.setData(content)
                const { indexText, storeText } = await customStore.getTextFiles()
                this.list = this.list.concat([
                    {
                        url: `${this.rootPath}/src/components/manage/${item.name}/index.tsx`,
                        text: indexText,
                    },
                    {
                        url: `${this.rootPath}/src/components/manage/${item.name}/store.ts`,
                        text: storeText
                    }
                ])
                if(content.lessStr){
                    this.list.push({
                        url: `${this.rootPath}/src/components/${item.name}/style.less`,
                        text: content.lessStr,
                    })
                }
            })()
        }))
    }

    
    /**
     * 写入管理端 页面信息
     */
    createAdminPages = async () => {
        const list = await Promise.all(this.adminPages.map((o) => {
            return (async () => {
                const { content, ...item } = o;
                const customStore = new CustomPageStore({ isBuild: true })
                await customStore.setData(content)
                const { indexText, storeText } = await customStore.getTextFiles()
                return {
                    ...item,
                    indexText,
                    storeText,
                    lessText: content.lessStr,
                }
            })()
        }))

        const map = new Map(list.map((o: any) => [o.id, o]));

        // console.log('this.adminMenus', this.adminMenus)
        const treeMenus = this.getTreeMenus(this.adminMenus);
        const flattenMenus = flattenTree(treeMenus);
        for (const menu of flattenMenus) {
            const item = map.get(menu.pageId);
            if(item){
                const path = menu.path.slice(1);
                // 判断当前页面是否已经使用到
                this.list = this.list.concat([
                    {
                        url: `${this.rootPath}/src/manages/${path}/index.tsx`,
                        text: item.indexText,
                    },
                    {
                        url: `${this.rootPath}/src/manages/${path}/store.ts`,
                        text: item.storeText
                    }
                ])
                if(item.lessText){
                    this.list.push({
                        url: `${this.rootPath}/src/manages/${path}/style.less`,
                        text: item.lessText,
                    })
                }
            }
        }
    }


    /**
     * 写入路由信息
     */
    createAppRoutes = async () => {
        // 获取routes 文件
        const index = this.list.findIndex((o) => o.url == "template/src/routes.ts")
        const item = this.list[index];
        let routeStr = item.text;
        
        const appMap = new Map(this.pages.map((o: any) => [o.id, o]));
        let startIndex = routeStr.indexOf('export const mainRoutes: IRoute[] = [') + 36;
        let endIndex = startIndex + routeStr.slice(startIndex).indexOf(']') + 1;
        let defaultRouteStr = routeStr.slice(startIndex, endIndex)
        // console.log('startIndex', startIndex, endIndex, defaultRouteStr)
        // 写入app 路由
        let defaultMenus = eval(defaultRouteStr);
        const loop = (list) => {
            return list.map((o) => {
                return {
                    name: o.name,
                    key: appMap.get(o.pageId)?.title,
                    path: o.path,
                    isLayout: o.type == 'layout'? true: undefined,
                    children: (o.children && o.children.length)? loop(o.children) : undefined,
                }
            })
        }
        let treeMenus = loop(this.getTreeMenus(this.menus))

        const menus = [
            ...defaultMenus,
            ...treeMenus,
        ]

        // console.log('menus', menus, this.menus, this.getTreeMenus(this.menus))

        // 将路由写入到文件中
        this.list[index].text = `${routeStr.slice(0,startIndex)}${JSON.stringify(menus, null, '\t')}${routeStr.slice(endIndex)}`;
    }


    /**
     * 写入管理段App 路由信息
     */
    createAdminRoutes = async () => {
        // 获取routes 文件
        const index = this.list.findIndex((o) => o.url == "template/src/routes.ts")
        const item = this.list[index];
        let routeStr = item.text;
        
        let startIndex = routeStr.indexOf('export const adminRoutes: IRoute[] = [') + 37;
        let endIndex = startIndex + routeStr.slice(startIndex).indexOf(']') + 1;
        let defaultRouteStr = routeStr.slice(startIndex, endIndex)
        // 写入app 路由
        let defaultMenus = eval(defaultRouteStr);
        const loop = (list) => {
            return list.map((o) => {
                // 写入到mianRoutes
                return {
                    name: o.name,
                    key: o.path,
                    path: `${o.path}`,
                    ignore: o.isShow? undefined : true,
                    children: (o.children && o.children.length)? loop(o.children) : undefined,
                }
            })
        }
        let treeMenus = loop(this.getTreeMenus(this.adminMenus))

        const menus = [
            ...defaultMenus,
            ...treeMenus,
        ]

        console.log('adminMenus', menus)

        // 将路由写入到文件中
        this.list[index].text = `${routeStr.slice(0,startIndex)}${JSON.stringify(menus, null, '\t')}${routeStr.slice(endIndex)}`;
    }


    /**
     * 写入config 配置信息
     */
    createConfig = async () => {
        const string = generateReadableJson(app.allVariablesSchema, app.extraInfo.configuration)

        /**
         * 追加写入config 配置信息
         */
        this.list.push({
            url: `${this.rootPath}/config/index.ts`,
            text: `export default ${string}`
        })
    }



    /**
     * 写入多语言配置信息
     */
    createLanguage = async () => {
        await language.reloadApp(this.languages);
        const mod = import.meta.glob('/packages/code/src/locales/lang/**.ts');


        for (const key of app.extraInfo.languageKeys) {

            const langVals = await mod[`/packages/code/src/locales/lang/${key}.ts`]().then((res) => res.default);
            this.list.push({
                url: `${this.rootPath}/src/locales/lang/${key}.ts`,
                text: `export default ${JSON.stringify(langVals, null, '\t')}`
            })
        }
    }



    /**
     * 写入文件信息
     */
    createFiles = async () => {
        const fileList = await file.updateFileList();
        // 合并到压缩包
        for (const item of fileList) {
            this.list.push({
                url: `${this.rootPath}/public${item.url}`,
                text: item.text,
            })
        }
    }


    /**
     * 构建生产环境包
     */
    init = async () => {
        // 加载应用数据
        await this.getAppProdInfo();
        // 加载模块基础压缩包
        this.list = await parseZipFile(dir.getWebCode());
        // 写入应用模块
        await this.createAppModules();
        // 写入应用页面信息
        await this.createAppPages();
        // 写入应用路由信息
        await this.createAppRoutes();
        // 写入管理端模块信息
        await this.createAdminModules();
        // 写入管理端 页面信息
        await this.createAdminPages();
        // 写入管理端路由信息
        await this.createAdminRoutes();
        // 写入config 配置信息
        await this.createConfig();
        // 写入多语言配置
        await this.createLanguage();
        // 文件
        await this.createFiles();

        // 创建压缩包，并下载(调试代码)
        // const time = Date.now().toString();
        // createZip(
        //     this.list.map((o) => ({ ...o, url: o.url.replace('template/', `${time}/`)})), 
        //     time
        // )

        return createZipFile(this.list);
    }
}


export default Prod;